+package cli_test
+
+import (
+	"context"
+	"fmt"
+	"testing"
+
+	"github.com/urfave/cli/v3"
+)
+
+// Reproduction for "nil pointer dereference due to HelpFlag when running in
+// parallel": the reporter's test, adapted to live in this repository.
+
+func RunCli(args []string) {
+	cmd := &cli.Command{
+		Name:  "debug",
+		Usage: "make an explosive entrance",
+		Action: func(_ context.Context, cmd *cli.Command) error {
+			return nil
+		},
+	}
+
+	if err := cmd.Run(context.Background(), args); err != nil {
+		fmt.Printf("%s\n", err)
+	}
+}
+
+type Case struct {
+	Name string
+	Args []string
+	Exit int
+}
+
+func Test_run(t *testing.T) {
+	t.Parallel()
+
+	tests := []Case{
+		{
+			Name: "hello_world",
+			Exit: 0,
+		},
+		{
+			Name: "hello_sunshine",
+			Exit: 0,
+		},
+	}
+	for _, tt := range tests {
+		t.Run(tt.Name, func(t *testing.T) {
+			t.Parallel()
+
+			defer func() {
+				if r := recover(); r != nil {
+					t.Errorf("unexpected panic - '%s' passing %s", r, tt.Args)
+				}
+			}()
+
+			RunCli(tt.Args)
+		})
+	}
+}
